import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";

const Login = (props) => {
  const [credentials, setCredentials] = useState({ email: "", password: "" });
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const response = await fetch("http://localhost:5000/api/auth/login", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          email: credentials.email,
          password: credentials.password,
        }),
      });

      const json = await response.json();
      console.log(json);
      
      if (json.success) {
        // Handle both possible token field names from backend
        const token = json.authtoken || json.authToken;
        if (token) {
          localStorage.setItem("token", token);

          if (props.refreshAuthState) {
            props.refreshAuthState();
          }

          props.showAlert("Welcome back! Successfully logged in.", "success");
          navigate("/");
        } else {
          console.error('No token received:', json);
          props.showAlert("Login successful but no token received", "warning");
        }
      } else {
        props.showAlert(json.error || json.message || "Invalid credentials", "danger");
      }
    } catch (error) {
      console.error('Login error:', error);
      props.showAlert("Login failed. Please check your connection and try again.", "danger");
    } finally {
      setLoading(false);
    }
  };

  const onChange = (e) => {
    setCredentials({ ...credentials, [e.target.name]: e.target.value });
  };

  return (
    <div className="container">
      <div className="row">
        <div className="col-md-6" style={{ maxWidth: '500px', margin: '0 auto' }}>
          <div className="card fade-in">
            <div className="card-header text-center">
              <div className="auth-header">
                <div className="auth-icon">
                  <i className="fas fa-sign-in-alt"></i>
                </div>
                <h2 className="mb-2">Welcome Back</h2>
                <p className="text-muted mb-0">Sign in to your Diary Desk account</p>
              </div>
            </div>
            <div className="card-body">
              <form onSubmit={handleSubmit}>
                <div className="form-group">
                  <label htmlFor="email" className="form-label">
                    <i className="fas fa-envelope me-2"></i>Email Address
                  </label>
                  <input
                    type="email"
                    className="form-control"
                    id="email"
                    value={credentials.email}
                    name="email"
                    onChange={onChange}
                    placeholder="Enter your email address"
                    required
                    autoComplete="email"
                  />
                </div>
                
                <div className="form-group">
                  <label htmlFor="password" className="form-label">
                    <i className="fas fa-lock me-2"></i>Password
                  </label>
                  <div className="password-input-group">
                    <input
                      type={showPassword ? "text" : "password"}
                      name="password"
                      className="form-control"
                      id="password"
                      value={credentials.password}
                      onChange={onChange}
                      placeholder="Enter your password"
                      required
                      autoComplete="current-password"
                    />
                    <button
                      type="button"
                      className="password-toggle"
                      onClick={() => setShowPassword(!showPassword)}
                      aria-label={showPassword ? "Hide password" : "Show password"}
                    >
                      <i className={`fas ${showPassword ? 'fa-eye-slash' : 'fa-eye'}`}></i>
                    </button>
                  </div>
                </div>

                <button
                  type="submit"
                  className="btn btn-primary btn-lg w-100"
                  disabled={loading || !credentials.email || !credentials.password}
                >
                  {loading ? (
                    <>
                      <div className="spinner me-2"></div>
                      Signing in...
                    </>
                  ) : (
                    <>
                      <i className="fas fa-sign-in-alt me-2"></i>Sign In
                    </>
                  )}
                </button>
              </form>

              <div className="auth-divider">
                <span>or</span>
              </div>

              <div className="auth-footer text-center">
                <p className="mb-0">
                  New to Diary Desk? 
                  <Link to="/signup" className="auth-link ms-1">
                    Create an account
                  </Link>
                </p>
              </div>
            </div>
          </div>

          {/* Welcome Message */}
          <div className="welcome-message text-center mt-4">
            <div className="welcome-features">
              <div className="feature-item">
                <i className="fas fa-shield-alt"></i>
                <span>Secure & Private</span>
              </div>
              <div className="feature-item">
                <i className="fas fa-cloud"></i>
                <span>Cloud Sync</span>
              </div>
              <div className="feature-item">
                <i className="fas fa-mobile-alt"></i>
                <span>Mobile Ready</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
